 static Dictionary<string,object> Snapshot(int seq,string phase,params Dictionary<string,object>[] rows){return new Dictionary<string,object>{{"kind","snapshot"},{"session","fixture"},{"sequence",seq},{"match_id",500},{"phase",phase},{"players",rows.Cast<object>().ToArray()}};}
